 void Get(std::span<std::byte>b){Need(bytes<=limit&&b.size()<=limit-bytes,"compound field span");bytes+=b.size();Raw(b);}uint8_t U8(){std::byte b;Get({&b,1});return std::to_integer<uint8_t>(b);}uint32_t U32(){uint32_t n=0;for(unsigned i=0;i<4;++i)n|=uint32_t(U8())<<(8*i);return n;}uint64_t U64(){uint64_t n=0;for(unsigned i=0;i<8;++i)n|=uint64_t(U8())<<(8*i);return n;}
