 const auto&e=c.record.expected.environment;for(auto*d:{&e.game,&e.compiler,&e.abi,&e.compile_inputs})w.Array(*d);w.Array(CanonicalProfile(c.input.profile));w.U64(c.input.hash);w.U32(uint32_t(c.input.hw_stage));w.U32(uint32_t(c.input.sw_stage));for(auto n:{c.input.start.unified,c.input.start.buffer,c.input.start.user_data})w.U32(n);w.U64(c.input.program_base);
