void SpvValid(const Companion&c){const auto&w=c.observed_spirv;Need(w.size()>=5&&w[0]==0x07230203&&w[1]>=0x10000&&w[1]<=c.input.profile.supported_spirv&&w[3]>0&&w[3]<=0x1000000&&w[4]==0,"actual SPIR-V header/domain");}
void WalkerValid(const Shader::CompileSnapshot&s){
 Need(s.flat.size()>=16&&std::equal(s.user_data.begin(),s.user_data.end(),s.flat.begin()),"owned flat userdata prefix mismatch");
 if(s.walker.empty()){Need(s.flat.size()==16,"flat extension without portable walker");return;}
 unsigned pointers=0,values=0;size_t copies=0;bool ended=false;std::vector<uint64_t>seen((s.flat.size()+63)/64);
 for(size_t at=0;at<s.walker.size();at+=3){auto op=s.walker[at],a=s.walker[at+1],b=s.walker[at+2];Need(op<=20&&!ended,"portable data-only walker opcode");
  if(op==0){Need(!a&&!b&&pointers==0&&at+3==s.walker.size(),"portable walker end");ended=true;}
  else if(op==1||op==2){Need(pointers<64&&!b&&(op==1||!a),"portable pointer stack");if(!pointers&&op==1)Need(a<=14,"portable root pointer span");++pointers;}
  else if(op==3){Need(pointers&&!a&&!b,"portable pop");--pointers;}
  else if(op==4||op==5){Need(pointers&&b>=16&&b<s.flat.size()&&(op==4||!a),"portable flat copy destination");auto mask=uint64_t(1)<<(b%64);Need(!(seen[b/64]&mask),"portable flat overwrite");seen[b/64]|=mask;++copies;}
  else if(op==6){Need(a<s.flat.size()&&!b,"portable AccFlat span");}
  else if(op==7)Need(!b,"portable immediate reserved operand");
  else if(op==8){Need(!a&&!b&&values<64,"portable value stack");++values;}
  else if(op==19)Need(!a&&!b,"portable not operands");
  else{auto required=op==20?2u:1u;Need(!a&&!b&&values>=required,"portable value pop");values-=required;}
 }
 Need(ended&&values==0&&copies==s.flat.size()-16,"portable walker coverage/stack");
}
Record Provisional(const Shader::CompileSnapshot&s,const Environment&e){Record r;r.expected=DescribeSnapshot(s,e);std::map<std::pair<uint32_t,uint32_t>,RegisterRead>reads;for(auto&a:s.register_reads){RegisterRead out;out.pointer_index=a.pointer_index;out.dword_offset=a.dword_offset;std::memcpy(out.words.data(),&a.buffer,16);auto[it,inserted]=reads.emplace(std::pair{a.pointer_index,a.dword_offset},out);Need(inserted||it->second==out,"conflicting actual reads");}for(auto&[key,v]:reads)r.reads.push_back(v);r.expected.register_reads_sha256=ReadsDigest(r.reads);return r;}
