 c.input.hash=r.U64();auto hw=r.U32(),sw=r.U32();Need((hw==1||hw==3||hw==5)&&sw==3,"companion stage");c.input.hw_stage=Shader::HwStage(hw);c.input.sw_stage=Shader::SwStage(sw);c.input.start.unified=r.U32();c.input.start.buffer=r.U32();c.input.start.user_data=r.U32();c.input.program_base=r.U64();
