std::array<std::byte,HeaderBytes>Header(size_t length,const Digest&sha){MemorySink w;for(char c:std::string_view("BEFCOMP1"))w.U8(c);w.U32(1);w.U32(0);w.U64(length);w.Array(sha);Need(w.b.size()==HeaderBytes,"compound header size");std::array<std::byte,HeaderBytes>b;std::copy(w.b.begin(),w.b.end(),b.begin());return b;}
std::pair<size_t,Digest>ReadHeader(std::span<const std::byte>b,size_t file_bytes){Need(b.size()==HeaderBytes&&file_bytes<=MaxItemBytes,"compound file bound");MemoryInput r(b,0);for(char c:std::string_view("BEFCOMP1"))Need(r.U8()==uint8_t(c),"compound magic");Need(r.U32()==1&&r.U32()==0,"compound version/flags");auto n=r.U64();Digest sha;r.Array(sha);Need(n==file_bytes-HeaderBytes&&n>0&&Nonzero(sha),"compound payload length");return{n,sha};}
void Fully(int fd,std::span<std::byte>b){size_t at=0;while(at<b.size()){auto n=read(fd,b.data()+at,b.size()-at);if(n<0&&errno==EINTR)continue;Need(n>0,"compound bounded read");at+=n;}}
struct stat FileShape(int fd){struct stat st{};Need(fstat(fd,&st)==0&&Owned(st,false)&&st.st_size>=HeaderBytes&&uint64_t(st.st_size)<=MaxItemBytes,"owned bounded compound file");return st;}
void Stable(const struct stat&a,const struct stat&b){Need(a.st_dev==b.st_dev&&a.st_ino==b.st_ino&&a.st_size==b.st_size&&a.st_mtimespec.tv_sec==b.st_mtimespec.tv_sec&&a.st_mtimespec.tv_nsec==b.st_mtimespec.tv_nsec,"compound changed during read");}
std::pair<size_t,Digest>CheckFile(int fd){auto before=FileShape(fd);Need(lseek(fd,0,SEEK_SET)==0,"compound seek header");std::array<std::byte,HeaderBytes>h;Fully(fd,h);auto[payload,expected]=ReadHeader(h,before.st_size);CC_SHA256_CTX hash;CC_SHA256_Init(&hash);std::array<std::byte,65536>chunk;size_t left=payload;while(left){auto n=std::min(left,chunk.size());Fully(fd,std::span(chunk).first(n));CC_SHA256_Update(&hash,chunk.data(),n);left-=n;}Digest actual;CC_SHA256_Final(actual.data(),&hash);Need(actual==expected,"compound payload digest mismatch");Stable(before,FileShape(fd));return{payload,expected};}
