size_t MemoryBytes(const Companion&c){
 const auto&s=c.input;Need(!HasSemanticProjection(s)&&!s.tess&&s.gs_copy.capacity()==0&&s.fetch,"raw complete companion only");
 Need(s.code.capacity()<=Shader::CompileSnapshot::MaxCodeBytes/4&&s.user_data.capacity()<=16&&s.flat.capacity()<=Shader::CompileSnapshot::MaxFlatBytes/4&&s.walker.capacity()<=Shader::CompileSnapshot::MaxWalkerBytes/4&&s.fetch->attributes.capacity()<=32&&s.register_reads.capacity()<=32&&c.record.expected.attributes.capacity()<=32&&c.record.reads.capacity()<=32&&c.observed_spirv.capacity()<=MaxItemBytes/4,"compound vector capacity bounds");
 const size_t n=sizeof(c)+(s.code.capacity()+s.user_data.capacity()+s.flat.capacity()+s.walker.capacity()+c.observed_spirv.capacity())*4+s.fetch->attributes.capacity()*sizeof(Shader::Gcn::VertexAttribute)+s.register_reads.capacity()*sizeof(Shader::CompileSnapshot::RegisterRead)+c.record.expected.attributes.capacity()*sizeof(Attribute)+c.record.reads.capacity()*sizeof(RegisterRead)+IoReserveBytes+(c.association?c.association->canonical_spec.capacity():0);Need(n<=MaxItemBytes,"compound owned Snapshot+SPV memory budget");return n;
}
bool FitsCounts(size_t code,size_t flat,size_t walker,size_t spv)noexcept{if(!code||code>Shader::CompileSnapshot::MaxCodeBytes/4||flat<16||flat>Shader::CompileSnapshot::MaxFlatBytes/4||walker>Shader::CompileSnapshot::MaxWalkerBytes/4||walker%3||spv<5||spv>MaxItemBytes/4)return false;constexpr size_t fixed=sizeof(Companion)+IoReserveBytes+BbFetchCapture::MaxStageBytes+32*(sizeof(Shader::Gcn::VertexAttribute)+sizeof(Shader::CompileSnapshot::RegisterRead)+sizeof(Attribute)+sizeof(RegisterRead));return(code+16+flat+walker+spv)*4<=MaxItemBytes-fixed;}
